# ============================================================
# PHANTOM KOI ALLIANCE — UNITAS 2026
# Ejercicio Blue Team: tasklist → taskkill → schtasks /delete
# Persistencia: Scheduled Task "PhantomKoi_Updater"
# ============================================================

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$gifB64 = ""

# Calcular tamaño real del GIF para ajustar ventana
$gifBytes     = [Convert]::FromBase64String($gifB64)
$stream       = New-Object System.IO.MemoryStream(,$gifBytes)
$gifImage     = [System.Drawing.Image]::FromStream($stream)
$gifW         = $gifImage.Width
$gifH         = $gifImage.Height

$formW = [Math]::Max($gifW + 40, 380)
$formH = $gifH + 100

$form = New-Object System.Windows.Forms.Form
$form.Text            = "*** PHANTOM KOI ALLIANCE — UNITAS 2026 ***"
$form.Size            = New-Object System.Drawing.Size($formW, $formH)
$form.StartPosition   = "CenterScreen"
$form.TopMost         = $true
$form.FormBorderStyle = "FixedDialog"
$form.BackColor       = [System.Drawing.Color]::FromArgb(30, 20, 20)
$form.MaximizeBox     = $false
$form.MinimizeBox     = $false

$picBox          = New-Object System.Windows.Forms.PictureBox
$picBox.Size     = New-Object System.Drawing.Size($gifW, $gifH)
$picBox.Location = New-Object System.Drawing.Point(20, 10)
$picBox.SizeMode = "Normal"
$picBox.BackColor = [System.Drawing.Color]::FromArgb(30, 20, 20)
$picBox.Image    = $gifImage

$lbl           = New-Object System.Windows.Forms.Label
$lbl.Text      = "Puerto Callao comprometido  :)  |  PKA 2026"
$lbl.ForeColor = [System.Drawing.Color]::FromArgb(220, 30, 30)
$lbl.BackColor = [System.Drawing.Color]::FromArgb(30, 20, 20)
$lbl.Font      = New-Object System.Drawing.Font("Consolas", 9, [System.Drawing.FontStyle]::Bold)
$lbl.AutoSize  = $false
$lbl.Size      = New-Object System.Drawing.Size(($formW - 40), 30)
$lbl.Location  = New-Object System.Drawing.Point(20, ($gifH + 18))
$lbl.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter

$form.Controls.Add($picBox)
$form.Controls.Add($lbl)

# No dejar cerrar con X — solo muere con taskkill
$form.Add_FormClosing({ $_.Cancel = $true })

[System.Windows.Forms.Application]::Run($form)
